    25	// NewMCPService creates an MCP service backed by the in-process API routes.
    26	func NewMCPService(profile *profile.Profile, echoServer *echo.Echo) (*MCPService, error) {
    27		spec, err := loadMCPServiceOpenAPISpec()
    28		if err != nil {
    29			return nil, err
    30		}
    31		registry, err := buildOperationRegistry(spec)
    32		if err != nil {
    33			return nil, err
    34		}
    35		tools, operationsByTool, err := buildCuratedTools(registry)
    36		if err != nil {
    37			return nil, err
    38		}
    39	
    40		version := "dev"
    41		if profile != nil && profile.Version != "" {
    42			version = profile.Version
    43		}
    44		server := sdkmcp.NewServer(&sdkmcp.Implementation{
    45			Name:    "memos",
    46			Version: version,
    47		}, nil)
    48	
    49		adapter := newAPIAdapter(echoServer)
    50		for _, tool := range tools {
    51			operation := operationsByTool[tool.Name]
    52			server.AddTool(tool, newMCPToolHandler(adapter, operation))
    53		}
    54	
    55		handler := sdkmcp.NewStreamableHTTPHandler(func(*http.Request) *sdkmcp.Server {
    56			return server
    57		}, &sdkmcp.StreamableHTTPOptions{
    58			Stateless:    true,
    59			JSONResponse: true,
    60			// memos is typically served behind a reverse proxy with the app bound to a
    61			// loopback address while the public Host header is a real domain. The SDK's
    62			// DNS-rebinding guard treats that shape as an attack and rejects every
    63			// request with 403 ("invalid Host header"). Disable it and rely on memos'
    64			// own Origin/Host allowlist (see RegisterRoutes -> isAllowedMCPOrigin) for
    65			// CSRF / DNS-rebinding protection instead.
    66			DisableLocalhostProtection: true,
    67		})
    68	
    69		return &MCPService{
    70			profile:          profile,
    71			operationsByTool: operationsByTool,
    72			handler:          handler,
    73		}, nil
    74	}
